<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, Plus, Ruler, Trash2, MessageCircle, MapPin } from 'lucide-vue-next'
import ActionButton from '@/components/verly/ActionButton.vue'
import StatusPill from '@/components/verly/StatusPill.vue'
import PieceDrawing from '@/components/verly/PieceDrawing.vue'
import { formatBRL, multiplyCents, toCents } from '@/lib/money'
import { addPreviewQuote } from './vendasPreviewState'
type QuoteItem={id:number;name:string;glass:string;color:string;width:number;height:number;quantity:number;leaves:number;unitCents:number}
const route=useRoute();const router=useRouter()
const data = [
 {id:'1',name:'Ana Exemplo',alias:'Ana Box',phone:'(11) 99999-4421',place:'Vila Mariana, São Paulo',quote:'Janela temperada',estimate:134000,width:120,height:80,color:'Incolor',measurement:'Falta visita técnica'},
 {id:'2',name:'Beatriz Teste',alias:'Bia Janela',phone:'(11) 99999-4422',place:'Moema, São Paulo',quote:'Box de correr',estimate:112000,width:150,height:190,color:'Verde',measurement:'Falta visita técnica'},
 {id:'3',name:'Rafael Teste',alias:'Rafa',phone:'(11) 99215-3170',place:'Ipiranga',quote:'Box de abrir',estimate:134000,width:120,height:195,color:'Incolor',measurement:'Medidas conferidas'},
 {id:'4',name:'Sílvia Exemplo',alias:'Sil',phone:'(11) 98652-9031',place:'Aclimação',quote:'Porta de correr',estimate:318000,width:240,height:205,color:'Incolor',measurement:'Medidas conferidas'},
 {id:'5',name:'João Exemplo',alias:'João',phone:'(11) 99000-0005',place:'Vila Mariana',quote:'Divisória',estimate:428000,width:260,height:210,color:'Incolor',measurement:'Medidas conferidas'},
 {id:'6',name:'Clara Teste',alias:'Clara',phone:'(11) 99000-0006',place:'Saúde',quote:'Espelho',estimate:92000,width:90,height:180,color:'Prata',measurement:'Medidas conferidas'},
 {id:'7',name:'Bruno Exemplo',alias:'Bruno',phone:'(11) 99000-0007',place:'Pinheiros',quote:'Espelho do lavabo',estimate:76000,width:0,height:0,color:'Prata',measurement:'Falta visita técnica'},
 {id:'8',name:'Pedro Teste',alias:'Pedro',phone:'(11) 99000-0008',place:'Lapa',quote:'Janela',estimate:145000,width:0,height:0,color:'Incolor',measurement:'Falta visita técnica'},
 {id:'232',name:'Paula Exemplo',alias:'Paula',phone:'(11) 98122-5400',place:'Moema',quote:'Janela de correr',estimate:247500,width:180,height:210,color:'Fumê',measurement:'Medidas conferidas'},
 {id:'219',name:'Caio Teste',alias:'Caio',phone:'(11) 98391-6108',place:'Endereço a confirmar',quote:'Peça a definir',estimate:0,width:0,height:0,color:'Incolor',measurement:'Falta visita técnica'},
 {id:'212',name:'Bianca Exemplo',alias:'Bianca',phone:'(11) 99571-1202',place:'Pinheiros',quote:'Espelho',estimate:76000,width:80,height:120,color:'Prata',measurement:'Falta visita técnica'},
 {id:'205',name:'Neto & Filhos Exemplo',alias:'Neto',phone:'(11) 98504-2109',place:'Lapa',quote:'Janela',estimate:145000,width:100,height:150,color:'Incolor',measurement:'Falta visita técnica'},
]
const clients=[...data,{...data[2]!,id:'229'},{...data[3]!,id:'224'}]
const knownClient=computed(()=>clients.find(c=>c.id===String(route.params.id)))
const client=computed(()=>({...knownClient.value, id:knownClient.value?.id||'',name:knownClient.value?.name||'Oportunidade não encontrada',alias:knownClient.value?.alias||'',phone:knownClient.value?.phone||'',place:knownClient.value?.place||'',when:'Conversa de exemplo · 15 out 2026',quote:knownClient.value?.quote||'',estimate:knownClient.value?.estimate||0,measurement:knownClient.value?.measurement||'Sem informações'}))
const items=ref<QuoteItem[]>([])
function loadItems(){const c=knownClient.value;items.value=c?[{id:1,name:c.quote,glass:'Temperado',color:c.color,width:c.width,height:c.height,quantity:1,leaves:1,unitCents:c.width&&c.height?c.estimate:0}]:[]}
loadItems();watch(()=>route.params.id,loadItems)
const needsVisit=computed(()=>client.value.measurement==='Falta visita técnica')
const message=computed(()=>`${client.value.quote}. ${needsVisit.value?'Podemos combinar uma visita para confirmar as medidas?':'Estas são as medidas que conversamos. Podemos preparar a proposta?'}`)
const validItem=(item:QuoteItem)=>!!item.name.trim()&&Number.isFinite(Number(item.width))&&Number(item.width)>0&&Number.isFinite(Number(item.height))&&Number(item.height)>0&&Number.isInteger(Number(item.quantity))&&Number(item.quantity)>0&&Number.isInteger(Number(item.leaves))&&Number(item.leaves)>0&&item.unitCents>0
const canSave=computed(()=>!!knownClient.value&&items.value.length>0&&items.value.every(validItem))
const totalCents=computed(()=>items.value.reduce((sum,item)=>sum+(validItem(item)?multiplyCents(item.unitCents,Number(item.quantity)):0),0))
const currency=formatBRL
const notice=ref('')
const removed=ref<QuoteItem>()
function addItem(){items.value.push({id:Date.now(),name:'Novo item',glass:'Temperado',color:'Incolor',width:0,height:0,quantity:1,leaves:1,unitCents:0});notice.value='Item adicionado. Preencha tipo e medidas.'}
function updatePrice(item:QuoteItem){const area=Number(item.width)*Number(item.height)/10000;const factor=(item.glass==='Laminado'?1.48:1)*(item.color==='Incolor'?1:item.color==='Fumê'?1.12:1.16);item.unitCents=Number.isFinite(area)&&area>0?multiplyCents(toCents(area*620),factor):0}
function removeItem(id:number){removed.value=items.value.find(item=>item.id===id);items.value=items.value.filter(item=>item.id!==id);notice.value='Item removido desta prévia.'}
function undoRemove(){if(removed.value)items.value.push(removed.value);removed.value=undefined;notice.value='Item restaurado.'}
function continueQuote(){
 if(!canSave.value)return
 const lines=items.value.map(item=>({name:item.name,glass:`${item.glass} · ${item.color}`,width:Number(item.width),height:Number(item.height),quantity:Number(item.quantity),leaves:Number(item.leaves),unitCents:item.unitCents}))
 const first=lines[0]!
 addPreviewQuote({customer:client.value.name,phone:client.value.phone,item:lines.length===1?first.name:`${lines.length} tipos de peça`,width:first.width,height:first.height,glass:lines.length===1?first.glass:'Vidros diversos',quantity:lines.reduce((n,line)=>n+line.quantity,0),totalCents:totalCents.value,profitCents:0,terms:'Condição de pagamento a combinar',items:lines})
 router.push({name:'Quotes'})
}
function backToLeads(){router.push({name:'Leads'})}
</script>

<template>
 <main class="preview-page quote-preview">
  <button class="qp-back" @click="backToLeads"><ArrowLeft :size="18"/> Voltar aos leads</button>
  <header class="qp-header"><div><p class="preview-eyebrow">Detalhe da oportunidade</p><h1 class="preview-heading">{{ client.name }}</h1><p class="preview-subtitle">{{ client.phone }} · {{ client.place }} · {{ client.when }}</p></div><StatusPill :tone="needsVisit?'pending':'neutral'">{{ client.measurement }}</StatusPill></header>
  <div class="qp-layout">
   <aside class="qp-context preview-surface"><header><span class="qp-icon"><MessageCircle :size="20"/></span><div><p class="preview-eyebrow">Pedido do cliente</p><h2>Conversa</h2></div></header><blockquote>“{{ message }}”</blockquote><div class="qp-context-meta"><span>{{ client.alias }} · {{ client.when }}</span><strong>Estimativa inicial {{ currency(client.estimate) }}</strong></div><section class="qp-measure-note" :class="{'needs-measure':needsVisit}"><Ruler/><div><strong>{{ needsVisit?'Combine uma visita técnica':'Medidas informadas pelo cliente' }}</strong><span>{{ needsVisit?'A visita confirma o tamanho real antes de fechar o orçamento.':'Confira as dimensões de cada peça antes de enviar.' }}</span></div></section><div class="qp-address"><MapPin :size="18" aria-hidden="true"/><span>{{ client.place }}</span></div></aside>
   <section class="qp-builder"><header class="qp-section-head"><div><p class="preview-eyebrow">Itens e medidas</p><h2>Monte o orçamento</h2><p>Confira cada peça e ajuste as informações.</p></div><button class="preview-button qp-add" @click="addItem"><Plus :size="18"/> Adicionar item</button></header>
    <article v-for="(item,index) in items" :key="item.id" class="qp-item preview-surface"><header class="qp-item-head"><div><span class="qp-number">{{ String(index+1).padStart(2,'0') }}</span><strong>Peça {{ index+1 }}</strong></div><button class="qp-remove" @click="removeItem(item.id)"><Trash2 :size="17"/> Remover item</button></header><div class="qp-item-content"><PieceDrawing v-if="item.width>0&&item.height>0" class="qp-piece" :width-cm="item.width" :height-cm="item.height" :label="item.name"/><div v-else class="qp-piece-placeholder"><Ruler/><span>Preencha largura e altura para ver o desenho</span></div><div class="qp-fields"><label class="preview-form-field qp-wide">Nome da peça<input v-model="item.name" type="text" placeholder="Ex.: box de banheiro"/></label><label class="preview-form-field">Largura (cm)<input v-model.number="item.width" type="number" min="1" step="0.1" @change="updatePrice(item)"/></label><label class="preview-form-field">Altura (cm)<input v-model.number="item.height" type="number" min="1" step="0.1" @change="updatePrice(item)"/></label><label class="preview-form-field">Folhas<input v-model.number="item.leaves" type="number" min="1" max="8"/></label><label class="preview-form-field">Quantidade<input v-model.number="item.quantity" type="number" min="1" max="99"/></label><label class="preview-form-field qp-wide">Tipo de vidro<select v-model="item.glass" @change="updatePrice(item)"><option>Temperado</option><option>Laminado</option></select></label><label class="preview-form-field qp-wide">Cor<select v-model="item.color" @change="updatePrice(item)"><option>Incolor</option><option>Fumê</option><option>Verde</option><option>Bronze</option></select></label><div class="qp-line-total"><span>{{ item.quantity }} × {{ currency(item.unitCents) }}</span><strong>{{ currency(item.unitCents*item.quantity) }}</strong></div></div></div></article>
    <p v-if="notice" class="preview-notice qp-notice" role="status">{{ notice }} <button v-if="removed" class="preview-button" @click="undoRemove">Desfazer</button></p>
    <section class="qp-total preview-surface"><div><span>Total estimado</span><strong>{{ currency(totalCents) }}</strong></div><p>O valor será recalculado ao ajustar o tipo de vidro ou as medidas.</p><ActionButton :disabled-reason="canSave ? undefined : 'Preencha as medidas e quantidades de todas as peças.'" @click="continueQuote">Salvar orçamento <ArrowLeft :size="17" class="qp-forward"/></ActionButton></section>
   </section>
  </div>
 </main>
</template>

<style scoped>
