6px;white-space:nowrap}.qp-item{padding:17px}.qp-item-head{display:flex;align-items:center;justify-content:space-between;padding-bottom:14px;border-bottom:1px solid #e1e7e4}.qp-item-head>div{display:flex;align-items:center;gap:10px}.qp-item-head strong{font-size:17px}.qp-number{display:grid;place-items:center;width:32px;height:32px;border-radius:9px;background:#edf4f2;color:#2d6863;font:600 15px var(--font-verly-mono)}.qp-remove{display:flex;align-items:center;gap:6px;min-height:44px;padding:7px 8px;border:0;border-radius:8px;background:transparent;color:#765039;font:500 15px var(--font-verly-body);cursor:pointer}.qp-remove:hover{background:#fff3e7}.qp-item-content{display:grid;grid-template-columns:minmax(130px,.72fr) minmax(0,1.5fr);gap:14px;padding-top:16px}.qp-piece{align-self:start;max-width:240px}.qp-piece-placeholder{display:grid;justify-items:center;align-content:center;gap:8px;min-height:150px;border:1px dashed #c5d2cd;border-radius:11px;background:#f7f9f8;color:#60706a;text-align:center;font-size:15px}.qp-piece-placeholder svg{color:#2e7d7a}.qp-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));align-content:start;gap:10px}.qp-fields :deep(.preview-form-field){gap:5px;color:#47544e;font-size:15px}.qp-fields :deep(input),.qp-fields :deep(select){width:100%;min-width:0;min-height:44px;padding:8px 9px;border:1px solid #bdcbc5;border-radius:8px;background:#fff;color:#141a1f;font:400 16px var(--font-verly-body)}.qp-wide{grid-column:span 2}.qp-line-total{display:grid;grid-column:1/-1;justify-items:end;gap:2px;padding-top:5px;color:#55625d;font-size:15px}.qp-line-total strong{font:600 18px var(--font-verly-mono);color:#141a1f}.qp-total{display:grid;gap:8px;padding:18px}.qp-total>div{display:flex;align-items:center;justify-content:space-between;gap:12px}.qp-total>div span{font-size:16px;color:#4c5b54}.qp-total>div strong{font:600 24px var(--font-verly-mono)}.qp-total>p{margin:0 0 7px;color:#596660;font-size:15px}.qp-total :deep(.verly-action-wrap){width:100%}.qp-total :deep(button){display:flex;align-items:center;justify-content:center;gap:9px;width:100%;min-height:50px}.qp-forward{transform:rotate(180deg)}.qp-notice{position:sticky;bottom:12px;justify-self:center}
@media(max-width:900px){.qp-layout{grid-template-columns:1fr}.qp-context{position:static}.qp-context blockquote{margin:12px 0}.qp-item-content{grid-template-columns:minmax(120px,.55fr) minmax(0,1.5fr)}}
@media(max-width:580px){.qp-header{align-items:flex-start;flex-direction:column}.qp-section-head{align-items:flex-start;flex-direction:column}.qp-item{padding:13px}.qp-item-content{grid-template-columns:1fr}.qp-piece{width:min(230px,100%);margin:auto}.qp-fields{grid-template-columns:repeat(2,minmax(0,1fr))}.qp-wide{grid-column:span 2}.qp-remove{font-size:15px}.qp-total>div strong{font-size:20px}}
